-- The measure the closing probe of issue 100366 reads: requests on workers that serve no active product host, from the daily Cloudflare GraphQL read in worker_usage_daily.
INSERT OR IGNORE INTO metric_registry
  (metric, layer, kind, formula, source_of_truth, target, owner, disposition_actor, refresh_cadence, state)
VALUES
  ('worker_requests_nonpublic_per_day', 'operational', 'leading',
   'requests_24h summed over the scripts of the latest worker_usage_daily day that are not the worker of an active product_registry row with a host (workers that serve no registered surface, so what they receive is the fleet observing itself: probes, crons, service calls). Exempt from a trigger: lever TP-2.3 (issue 100366, transformation_levers tp 2 n 3) owns it and its closing probe reads it, a trigger would file the same work twice (TP-2 exit: under 3000)',
   'qnfo-audit.worker_usage_daily x qnfo-audit.product_registry (fleet task self-observation-metric, hourly)', '< 3000', 'qnfo-fleet-control', 'fleet:self-observation-metric', '1h', 'UNMEASURED');

INSERT OR IGNORE INTO metric_breach_cause (metric_key, cause_key) VALUES ('worker_requests_nonpublic_per_day', 'structure');

INSERT OR IGNORE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('self-observation-metric', 'Requests on workers with no registered product surface (TP-2.3 exit measure)', 'workflow',
  json_object('steps', json_array(
    json_object('name', 'measure', 'type', 'sql', 'db', 'AUDIT', 'sql',
      'UPDATE metric_registry SET last_value = CAST((SELECT COALESCE(SUM(requests_24h), 0) FROM worker_usage_daily WHERE day = (SELECT MAX(day) FROM worker_usage_daily) AND script <> ''__unknown__'' AND script NOT IN (SELECT worker FROM product_registry WHERE state = ''active'' AND host LIKE ''%.%'' AND worker IS NOT NULL)) AS TEXT), last_refreshed = datetime(''now''), state = ''MEASURED'' WHERE metric = ''worker_requests_nonpublic_per_day''')
  )), 30000, 1, 1, 1, datetime('now'));

INSERT OR IGNORE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('self-observation-metric-1h', '25 * * * *', 'self-observation-metric', 1, 'UTC', datetime('now'));

-- Two gaps the read found, each with a doer and a closing probe.
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'WATCHMAKER-FALSE-UNMEASURED-1: one overloaded D1 read at 07:00Z froze the watchmaker index at 42 for the whole day',
'Charter pillar: autonomy (RM-MONITOR-THE-MONITORS-1, RM-TP-2-ONE-KERNEL). Metric it should move: watchmaker_index (METRIC-TRIGGER-357-WATCHMAKER-INDEX, issue 99909).

Evidence (qnfo-audit watchmaker_runs, read 2026-11-04): index_value was 1 or 2 on each of the 13 days from 2026-10-22 (code-task-merge, reader-report); on 2026-11-04 it was 42 because watchmakerDaily measured once, at 07:00Z, while D1 was overloaded, and 41 operations read "unmeasured: D1_ERROR: D1 DB is overloaded. Too many resources consumed within a 10 second window". watchmakerMeasure counts an unmeasured operation as needing a person (right when the read is real) and watchmakerDaily then skips the rest of the day ("already measured"), so a transient read error is frozen for 24 hours and files a critical breach for 41 operations that are healthy. The day also detects a stalled monitor up to 24 hours late.

Change: in qnfo-fleet-dashboard watchmakerMeasure, retry each operation once after a short pause when the error is a transient D1 error (overloaded, timed out, network connection lost); in watchmakerDaily, when the stored day has operations still unmeasured, measure again on later hourly ticks (at most 6 more times a day) and replace the day only when the new run has fewer unmeasured operations. Keep counting an operation that stays unmeasured. Add a case to the dashboard suite that replays the 2026-11-04 shape (every read throws overloaded once, then succeeds) and expects index equal to the real stalled count. Prediction: no day with more than 3 unmeasured operations in watchmaker_runs after the deploy.

code-task: repo=qnfo-workers path=qnfo-fleet-dashboard/worker.js
code-anchor: async function watchmakerMeasure(env, nowMs) {
code-probe: {"paths": ["qnfo-fleet-dashboard/worker.js"], "contains": "WATCHMAKER-RETRY-1"}',
'c5-observe', 'reliability', 'high', 'open', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE status = 'open' AND title = 'WATCHMAKER-FALSE-UNMEASURED-1: one overloaded D1 read at 07:00Z froze the watchmaker index at 42 for the whole day');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'CF-CAPABILITY-ADOPT-1: the capability catalog has no adopt leg, 15 session-made proposals sit undecided',
'Charter pillar: autonomy (RM-CAPABILITY-PRODUCT-LOOP-1). Metric it should move: cf_changelog_open_proposals_14d (today 2, counting only rows the changelog created).

Evidence (qnfo-audit, read 2026-11-04): cloudflare_capability_catalog has 15 rows in status proposed written by the 2026-10-02 session audit (account-notifications, cron-single-trigger, turnstile, access-owner-control, analytics-engine, d1-time-travel, r2-event-notifications, gradual-deployments, rate-limiting-binding, vectorize-consolidation, secrets-store, ai-crawl-control, waf, app-caching, cfc-clef) and 4 not_considered. Nine link issues that are all closed (1683, 1711, 1757, 1758, 1762, 1782, 1785 twice, 498 resolved) so no doer is left, six link none. cfcMetrics counts only rows that cf_changelog_items marks reopened or new-row, so these never raise cf_changelog_open_proposals_14d, and nothing writes the decision back: turnstile is in use (Turnstile siteverify calls in 7 workers) and gradual-deployments is built (deploys_via_gradual 0.0032) while both read proposed. The design (docs/CLOUDFLARE-CAPABILITY-INTEGRATION.md components 4 and 5) has an advisor decision and a before/after metric write-back; neither exists.

Change in qnfo-fleet-control: cfcMetrics counts every catalog row in proposed or not_considered older than 14 days whatever created it; cfcRun files at most 2 a day of one deduped issue per such row that has no OPEN linked issue, titled CF-CAPABILITY-DECIDE-1: <slug>, carrying need, product, when_to_choose, metric_ref and its metric''s current value, with the definition of done: status becomes in_use (with the evidence), approved (with a linked issue naming the work), reviewing or rejected (with the reason appended), and linked_issue points at the open issue. Prediction: undecided rows older than 14 days with no open linked issue go from 15 to 0 within 14 days; the metric stays below its trigger threshold of 5.

code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js
code-anchor: async function cfcMetrics(env) {
code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "CF-CAPABILITY-DECIDE-1"}',
'c5-observe', 'optimization', 'medium', 'open', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE status = 'open' AND title = 'CF-CAPABILITY-ADOPT-1: the capability catalog has no adopt leg, 15 session-made proposals sit undecided');
